from PIL import Image
import numpy as np
im=Image.open('image.png').convert('RGB')
a=np.array(im).astype(int)
H,W,_=a.shape
def blobs(mask):
    ys,xs=np.where(mask); lab=np.zeros((H,W),bool); out=[]
    for y,x in zip(ys,xs):
        if lab[y,x]: continue
        st=[(y,x)]; lab[y,x]=True; pts=[]
        while st:
            cy,cx=st.pop(); pts.append((cy,cx))
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not lab[ny,nx]:
                        lab[ny,nx]=True; st.append((ny,nx))
        P=np.array(pts); out.append((P[:,1].mean(),P[:,0].mean(),len(P),P[:,1].min(),P[:,1].max(),P[:,0].min(),P[:,0].max()))
    return sorted(out)
def col(c,tol=3): return (np.abs(a-np.array(c)).sum(axis=2)<=tol)
for name,c in [('centre yellow',(255,213,79)),('centre orange',(255,179,0)),('centre brown',(109,76,65))]:
    for b in blobs(col(c)): print(name,'at x=%.1f y=%.1f px=%d'%b[:3])
# petal blobs per colour and petal counts via angular profile
petals={'pink':(244,143,177),'orange':(255,183,77),'purple':(206,147,216),'red':(239,83,80),'white':(250,250,250)}
# find blue petal colour: look near x~540,y~275
from collections import Counter
cnt=Counter(tuple(int(v) for v in a[y,x]) for y in range(255,300) for x in range(515,565))
print('blue flower region colours', cnt.most_common(6))
"

