import json, numpy as np
comps=json.load(open('comps.json')); byid={c['id']:c for c in comps}
order=[46,45,40,35,25,22,17,13,24,28,36,38,41,44,43,42,39,32,23,19,14,10,9,11,12,15,18,21,26,29,30,33,37,34,31,27,20,16,6,4,2,1,3,5,7]
def ends(i): c=byid[i]; return np.array(c['e1']),np.array(c['e2'])
tot=sum(byid[i]['L'] for i in order)
for k in range(len(order)-1):
    a1,a2=ends(order[k]); b1,b2=ends(order[k+1])
    tot+=min(np.linalg.norm(p-q) for p in (a1,a2) for q in (b1,b2))
print('measured visible dashed length ~ %.0f px'%tot)
M={'K':'-.-','E':'.','Y':'-.--','I':'..','S':'...','4':'....-','8':'---..','2':'..---','1':'.----','9':'----.'}
def units(msg):
    u=0
    for wi,w in enumerate(msg.split(' ')):
        if wi: u+=7
        for li,l in enumerate(w):
            if li: u+=3
            code=M[l]; u+=sum(3 if s=='-' else 1 for s in code)+len(code)-1
    return u
full=units('KEY IS 48219')+7          # message + trailing word gap
partial=units('KE')+3+ (3+1+1+1+3)     # 'K','E' then '-.-' of Y (visible before bee)
print('predicted: one cycle = %d units = %d px; visible = %d units = %d px (4 px/unit)'%(full,full*4,full+partial,(full+partial)*4))
"

